import{z as N,x as B,o as t,c as A,q as o,j as i,D as e,d as n,s,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"非规格化与 NaN","description":"","frontmatter":{"title":"非规格化与 NaN","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/denormal-nan.md","filePath":"cs/denormal-nan.md","lastUpdated":1791413859000}'),d={name:"cs/denormal-nan.md"};function p(m,a,C,h,u,c){const r=B("Mermaid");return t(),A("div",null,[a[2]||(a[2]=o('<h1 id="非规格化与-nan" tabindex="-1">非规格化与 NaN <a class="header-anchor" href="#非规格化与-nan" aria-label="Permalink to &quot;非规格化与 NaN&quot;">​</a></h1><div class="epigraph"><p>规格化格子在零前有一道悬崖；非规格化把台阶接着铺下去。NaN 则是「这不是一个数」的合法位型，不是溢出后的某个很大的整数。</p><footer>—— 据 IEEE Std 754-2008；Goldberg, What Every Computer Scientist Should Know About Floating-Point Arithmetic, 1991 整理</footer></div><p>上一课<a href="/cs/rounding-modes">舍入模式</a>钉死了理想结果往格子哪一侧靠。<a href="/cs/ieee-754">IEEE 754</a>已经标出指数全 \\(0\\) / 全 \\(1\\) 的槽位。本课不重讲偏置，也不从「异常处理」另起。缺口是：规格化最小正数以下，若直接跳到零，相对误差突然炸开；无效运算若仍交回某个有限数，后课分支会把「不是数」当成很大或很小。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>规格化要求隐藏首位为 \\(1\\)，最小正数是 \\(2^{1-\\mathrm{bias}}\\) 量级。再小的理想结果，若 flush-to-zero，就变成零——这是硬下溢。缺口之一是<strong>渐近下溢</strong>：指数全 \\(0\\) 时改读 \\(0.f\\times 2^{1-\\mathrm{bias}}\\)，用显式尾数填零附近的洞，有效位数随幅值下降。</p><p><span class="marginnote">数字实例：单精度 bias 为 127，规格化最小正数是 \\(2^{1-126}=2^{-126}\\approx 1.18\\times 10^{-38}\\)；非规格化把台阶继续铺到 \\(2^{-149}\\approx 1.4\\times 10^{-45}\\)，比「直接跳到零」多出约七个数量级的过渡带。在 flush-to-zero 的机器上，这一整段数统统变 0，误差不再是「差一点」而是「相对误差 100%」。</span></p><p>缺口之二：指数全 \\(1\\)、尾数非 \\(0\\) 是 NaN。比较无序；加法传播 NaN。上一课的舍入假定结果仍是实数邻居；NaN 没有「最近的实数」。quiet / signaling 与载荷是 2008 写清的细节，本课只钉到够后课哈希与分支不踩坑。</p><h3 id="nan-不是「出错的补码」" tabindex="-1">NaN 不是「出错的补码」 <a class="header-anchor" href="#nan-不是「出错的补码」" aria-label="Permalink to &quot;NaN 不是「出错的补码」&quot;">​</a></h3><p>整数溢出仍是某个补码字。NaN 与任何有限值、与无穷的无序比较，不能用上一课有符号溢出旗标代替。把 NaN 当成 <code>INT_MAX</code>，排序和 <code>==</code> 都会错：NaN \\(\\neq\\) NaN 在 754 里是规定。</p><p><span class="marginnote">754-2008 把 subnormal 与 NaN 编码写进交换格式。Goldberg 用渐近下溢解释为什么零附近不要一道悬崖。Flush-to-zero 是实现加速选项，不是默认交换语义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>指数全 \\(0\\)、尾数全 \\(0\\)：有符号零（上一课已区分比特与数值）。指数全 \\(0\\)、尾数非 \\(0\\)：非规格化。指数全 \\(1\\)、尾数全 \\(0\\)：\\(\\pm\\infty\\)。指数全 \\(1\\)、尾数非 \\(0\\)：NaN；最高尾数位通常区分 quiet 与 signaling。算术：非数参与则结果常为 qNaN；sNaN 参与则发 invalid。本课不把五类异常接到陷阱入口。</p>',12)),(t(),i(l,null,{default:e(()=>[s(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPEC%5B%22%E8%A7%84%E6%A0%BC%E5%8C%96%E6%A0%BC%E5%AD%90%22%5D%20--%3E%20UND%5B%22%E9%9D%9E%E8%A7%84%E6%A0%BC%E5%8C%96%EF%BC%9A%E5%A1%AB%E9%9B%B6%E9%99%84%E8%BF%91%22%5D%0A%20%20SPEC%20--%3E%20INF%5B%22%E6%97%A0%E7%A9%B7%22%5D%0A%20%20SPEC%20--%3E%20NAN%5B%22NaN%EF%BC%9A%E6%97%A0%E5%BA%8F%22%5D%0A%20%20UND%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%90%8C%E4%B8%80%E4%B8%B2%E4%B8%8D%E5%BD%93%E6%95%B0%E8%AF%BB%22%5D%0A%20%20NAN%20--%3E%20LATER%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"舍入仍适用：下溢时先谈精确结果再映射到非规格化或零。模式朝零时，很小的数更容易变成零。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"有了非规格化，交换位型在零附近连续到 \\(2^{1-\\mathrm{bias}-p}\\) 量级（\\(p\\) 为尾数精度）。软浮点与部分 GPU 路径仍 flush-to-zero，结果不可与 754 默认逐比特比。NaN 载荷可携带诊断，但可移植代码不能依赖载荷值。后课文本编码开始后，浮点位型不再改；同一比特串改读字符是另一套约定。",-1)),a[6]||(a[6]=E("p",null,"拿到一个浮点位型，先看指数段落在哪个区间，读法就定了：",-1)),(t(),i(l,null,{default:e(()=>[s(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E8%AF%BB%E4%B8%80%E4%B8%AA%E6%B5%AE%E7%82%B9%E4%BD%8D%E5%9E%8B%22%5D%20--%3E%20E0%7B%22%E6%8C%87%E6%95%B0%E6%AE%B5%E5%85%A8%200%EF%BC%9F%22%7D%0A%20%20E0%20--%3E%7C%22%E6%98%AF%22%7C%20M0%7B%22%E5%B0%BE%E6%95%B0%E6%AE%B5%E5%85%A8%200%EF%BC%9F%22%7D%0A%20%20M0%20--%3E%7C%22%E6%98%AF%22%7C%20ZERO%5B%22%C2%B10%22%5D%0A%20%20M0%20--%3E%7C%22%E5%90%A6%22%7C%20SUB%5B%22%E9%9D%9E%E8%A7%84%E6%A0%BC%E5%8C%96%EF%BC%9A0.f%20%C3%97%202%5E(1%E2%88%92bias)%22%5D%0A%20%20E0%20--%3E%7C%22%E5%90%A6%22%7C%20E1%7B%22%E6%8C%87%E6%95%B0%E6%AE%B5%E5%85%A8%201%EF%BC%9F%22%7D%0A%20%20E1%20--%3E%7C%22%E5%90%A6%22%7C%20NORM%5B%22%E8%A7%84%E6%A0%BC%E5%8C%96%EF%BC%9A1.f%20%C3%97%202%5E(e%E2%88%92bias)%22%5D%0A%20%20E1%20--%3E%7C%22%E6%98%AF%22%7C%20M1%7B%22%E5%B0%BE%E6%95%B0%E6%AE%B5%E5%85%A8%200%EF%BC%9F%22%7D%0A%20%20M1%20--%3E%7C%22%E6%98%AF%22%7C%20INF%5B%22%C2%B1%E2%88%9E%22%5D%0A%20%20M1%20--%3E%7C%22%E5%90%A6%22%7C%20NAN%5B%22NaN%EF%BC%9A%E6%9C%80%E9%AB%98%E5%B0%BE%E6%95%B0%E4%BD%8D%E5%88%86%20quiet%20%2F%20signaling%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">直觉类比：规格化数像固定有效位数的科学计数法，铺到最小刻度就断崖；非规格化像允许有效数字逐级让位——数越小、有效位数越少，但台阶一直连到零附近，不会一跤跌进零。代价是小数的相对精度变差，这是用精度换连续性的交易。</span></p><p><span class="marginnote">常见误区：初学者容易把 NaN 想成「一个特别大的出错数字」。它是合法位型，与任何数（包括它自己）的比较都是「无序」，所以 <code>x == x</code> 为假反而是检测 NaN 的老办法；排序或哈希若不特判 NaN，整个结果的顺序和分组都会错乱，而不是只错那一个数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲十进制非规格化，不把 NaN boxing 当语言实现细节展开。字符、码位与数值无关，从<a href="/cs/char-unicode">下一课</a>起换对象。</p><p>后课默认：单/双精度按 754 读；零附近有非规格化；NaN 无序且 \\(\\mathrm{NaN}\\neq\\mathrm{NaN}\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>非规格化填规格化最小正数与零之间的洞，精度下降。</li><li>NaN 是合法位型，比较无序；不是补码溢出值。</li><li>Flush-to-zero 会改变交换语义。</li><li>出处：IEEE 754-2008；Goldberg, 1991。</li></ul>',7))])}const b=N(d,[["render",p]]);export{D as __pageData,b as default};
